CREATE FUNCTION public.prevent_gallery_cycles() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.parent_id IS NOT NULL AND EXISTS (WITH RECURSIVE ancestors AS (SELECT id,parent_id FROM public.galleries WHERE id=NEW.parent_id UNION SELECT g.id,g.parent_id FROM public.galleries g JOIN ancestors a ON g.id=a.parent_id) SELECT 1 FROM ancestors WHERE id=NEW.id) THEN RAISE EXCEPTION 'Una galleria non può contenere se stessa'; END IF; RETURN NEW; END $$;
CREATE TRIGGER prevent_gallery_cycles BEFORE INSERT OR UPDATE OF parent_id ON public.galleries FOR EACH ROW EXECUTE FUNCTION public.prevent_gallery_cycles();